WITH ins AS (INSERT INTO sais_resources (resource_id, family_key, document_number, resource_category, subcategory, jurisdiction_level, jurisdiction, organization_name, organization_type, service_type, official_url, official_contact, statutory_authority, verification_status, last_verified_at, notes, revision) VALUES 
('SAIS-EC-008-01', 'systemic_abuse_intelligence', 308, 'elder_self_neglect', 'elder_self_neglect_capacity_versus_choice', 'state', 'state -- ALL_STATES', 'Capacity Versus Choice -- A Competent Adult May Live Unwisely', 'state_agency | healthcare_provider', 'elder_self_neglect_capacity_versus_choice', 'https://eldercare.acl.gov/', 'Adult Protective Services via Eldercare Locator: 800-677-1116 | The older adult''s primary care provider | Area Agency on Aging: 800-677-1116', 'State adult protective services acts (self-neglect provisions) | Elder Justice Act (42 U.S.C. sec. 1397j et seq.) | Americans with Disabilities Act (42 U.S.C. sec. 12101) | Olmstead v. L.C., 527 U.S. 581 (1999) | State guardianship codes and capacity standards.', 'VERIFIED', '2026-08-17', 'SEPARATE ''I DISAGREE WITH THIS CHOICE'' FROM ''THIS PERSON CANNOT UNDERSTAND THE CHOICE.'' Only the second one opens any legal door, and treating the first as if it were the second is how families lose access to the person entirely. If capacity is genuinely in question, ask their own clinician for a decision-specific assessment at baseline -- not during a hospitalization, when delirium is routinely mistaken for permanent incapacity. [address_resolution: Resolve via the state agency''s LOCAL OFFICE locator; input = ZIP or county. Most state agencies operate county or district offices rather than a single statewide address.] [doc_code: EC-008 | pipeline: Elder Self-Neglect] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: e6f1d442fa33d6b80ac74ae333b5ccb97eeb5213832e362c10415ed17df02659]', 'v1.0'),
('SAIS-EC-008-02', 'systemic_abuse_intelligence', 308, 'elder_self_neglect', 'elder_self_neglect_reversible_causes', 'federal + state', 'federal + state -- ALL_STATES', 'Reversible Causes -- What Is Actually Driving the Decline', 'healthcare_provider | federal_agency', 'elder_self_neglect_reversible_causes', 'https://eldercare.acl.gov/', 'The older adult''s primary care provider | Area Agency on Aging: 800-677-1116 | 988 Suicide and Crisis Lifeline | HHS Office for Civil Rights (records): 800-368-1019', 'Older Americans Act (42 U.S.C. sec. 3001 et seq.) | Medicare annual wellness visit and cognitive assessment (42 U.S.C. sec. 1395x(hhh)) | HIPAA right of access (45 CFR 164.524) | Elder Justice Act (42 U.S.C. sec. 1397j et seq.)', 'VERIFIED', '2026-08-17', 'SCREEN FOR DEPRESSION, DELIRIUM, MEDICATION EFFECTS, SENSORY LOSS, AND POVERTY BEFORE CONCLUDING ANYTHING IS A CHOICE. All five are common, all five look like refusal from the outside, and all five are treatable. The poverty one in particular is routinely misread as stubbornness -- an older adult who cannot afford heat and will not say so looks exactly like an older adult who has decided not to heat the house. [address_resolution: Resolve via HRSA findahealthcenter.hrsa.gov for sliding-scale sites; input = ZIP. For a specific provider, use the state licensing registry.] [doc_code: EC-008 | pipeline: Elder Self-Neglect] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 74270089210cb7819f0d06e57a626edb6f4b7ab84c93541c2b5b0fb1dbd63fa2]', 'v1.0'),
('SAIS-EC-008-03', 'systemic_abuse_intelligence', 308, 'elder_self_neglect', 'elder_self_neglect_aps_role', 'state', 'state -- ALL_STATES', 'Adult Protective Services in a Self-Neglect Case', 'state_agency', 'elder_self_neglect_aps_role', 'https://eldercare.acl.gov/Public/Index.aspx', 'Adult Protective Services via Eldercare Locator: 800-677-1116 | 911 for immediate danger | Your state APS -- see jurisdiction table', 'State adult protective services acts, self-neglect provisions | Elder Justice Act (42 U.S.C. sec. 1397j et seq.) | Older Americans Act (42 U.S.C. sec. 3001 et seq.) | State emergency protective services statutes.', 'VERIFIED', '2026-08-17', 'REPORT, BUT EXPECT THE RIGHT OUTCOME RATHER THAN THE ONE YOU WANT. If the person has capacity and declines, APS documenting and closing is the system working. Re-report on material worsening -- escalating patterns are tracked and do change the assessment. And confirm no one else is responsible for the person''s care; if someone is, this is not self-neglect and belongs in the Elder Neglect pipeline, where the leverage is completely different. [address_resolution: Resolve via the state agency''s LOCAL OFFICE locator; input = ZIP or county. Most state agencies operate county or district offices rather than a single statewide address.] [doc_code: EC-008 | pipeline: Elder Self-Neglect] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: f1be03fa52ed2c7072ed9e172c014220cd627bf94e98edaa619b5f36441cd80e]', 'v1.0'),
('SAIS-EC-008-04', 'systemic_abuse_intelligence', 308, 'elder_self_neglect', 'elder_self_neglect_voluntary_supports', 'federal + state', 'federal + state -- ALL_STATES', 'Voluntary Services -- The Aging Network, HCBS, and Benefits', 'federal_program | state_agency', 'elder_self_neglect_voluntary_supports', 'https://acl.gov/programs', 'Eldercare Locator / Area Agency on Aging: 800-677-1116 | Dial 211 | Your state Medicaid agency | Your state SHIP for Medicare counseling', 'Older Americans Act Title III (42 U.S.C. sec. 3030d, 3030e -- supportive and nutrition services) | Medicaid Home and Community-Based Services (42 U.S.C. sec. 1396n(c), (i), (k)) | Medicaid fair hearing and continuation (42 CFR 431.230) | LIHEAP (42 U.S.C. sec. 8621) | Weatherization Assistance Program (42 U.S.C. sec. 6861)', 'VERIFIED', '2026-08-17', 'START WITH HOME-DELIVERED MEALS. It is the most commonly accepted offer, it costs the person nothing, and it puts a human being at the door regularly who will notice deterioration and report it -- which is the visibility a family loses when the person withdraws. Lead with the service they will say yes to, not the one you think is most urgent. [address_resolution: Resolve via the program''s grantee or local-provider locator; input = ZIP or county. Federal programs deliver through local grantees with their own addresses.] [doc_code: EC-008 | pipeline: Elder Self-Neglect] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 090266ed4d60043d6bab86da22c08ae2732607d1719b6b3e44aa0e201215eb13]', 'v1.0'),
('SAIS-EC-008-05', 'systemic_abuse_intelligence', 308, 'elder_self_neglect', 'elder_self_neglect_housing_and_code', 'federal + state', 'federal + state -- ALL_STATES', 'Housing Risk -- Hoarding, Code Violations, and the Eviction or Condemnation Threat', 'local_government | federal_agency', 'elder_self_neglect_housing_and_code', 'https://www.hud.gov/topics/housing_discrimination', 'Local code enforcement | Your local fair housing agency | HUD Housing Discrimination Hotline: 800-669-9777 | Dial 211 for legal aid', 'Fair Housing Act (42 U.S.C. sec. 3601 et seq.; reasonable accommodation at sec. 3604(f)(3)(B)) | Section 504, Rehabilitation Act (29 U.S.C. sec. 794) | ADA Title II (42 U.S.C. sec. 12131) | Public housing grievance procedures (24 CFR Part 966) | State landlord-tenant and code enforcement statutes.', 'VERIFIED', '2026-08-17', 'REQUEST A REASONABLE ACCOMMODATION IN WRITING THE MOMENT HOUSING IS THREATENED. Hoarding disorder and many cognitive conditions are disabilities under fair housing law, the accommodation sought is usually just TIME AND A PLAN, and it can be requested even after an eviction case is filed. And do not accept a forced cleanout as the solution -- remediation without clinical support reliably relapses and destroys the trust the next intervention depends on. [address_resolution: Resolve via the county or municipal office for the property location; input = property address.] [doc_code: EC-008 | pipeline: Elder Self-Neglect] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 06d2b49fe387335affa892a30f8aa774d3b5b3b24b94ac8a9d04b54561c4525f]', 'v1.0'),
('SAIS-EC-008-06', 'systemic_abuse_intelligence', 308, 'elder_self_neglect', 'elder_self_neglect_protective_intervention', 'state', 'state -- ALL_STATES', 'Protective Intervention as Last Resort -- and the Alternatives That Come First', 'state_court | state_agency', 'elder_self_neglect_protective_intervention', 'https://www.americanbar.org/groups/law_aging/', 'Your probate or guardianship court | Adult Protective Services: 800-677-1116 | State protection and advocacy agency | Your state bar lawyer referral service', 'UGCOPAA (2017) sec. 301 (least restrictive), sec. 310 (limited guardianship), sec. 318 (termination and restoration) | UAGPPJA | State emergency protective services statutes | Social Security representative payee (42 U.S.C. sec. 405(j)) | Olmstead v. L.C., 527 U.S. 581 (1999)', 'VERIFIED', '2026-08-17', 'ASK WHETHER A REPRESENTATIVE PAYEE PLUS IN-HOME SERVICES WOULD SOLVE THE ACTUAL PROBLEM BEFORE ANYONE FILES FOR GUARDIANSHIP. A very large share of self-neglect cases that look like they require a guardian are really an income-management problem plus an unmet care need, and that combination is reversible, cheap, and leaves the person''s rights intact. If a proceeding is unavoidable, ask for a LIMITED order covering only the decisions actually at issue. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [doc_code: EC-008 | pipeline: Elder Self-Neglect] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 1bb0bcd6c35c02aefa537cb2842a4eb2959836e3f63293d29b1e839cd4bbf5d5]', 'v1.0'),
('SAIS-EC-009-01', 'systemic_abuse_intelligence', 309, 'power_of_attorney_abuse', 'poa_abuse_instrument_review', 'state', 'state -- ALL_STATES', 'Read the Power of Attorney First -- Most Abuse Exceeds the Document', 'state_court | legal_aid', 'poa_abuse_instrument_review', 'https://www.uniformlaws.org/', 'County recorder (for recorded POAs affecting real property) | Your state bar lawyer referral service | Dial 211 for legal aid and elder law referrals', 'Uniform Power of Attorney Act (2006), esp. sec. 201 (authority requiring express grant) and sec. 301 (statutory form) | State durable power of attorney statutes | State notary and recording acts.', 'VERIFIED', '2026-08-17', 'COMPARE EVERY TRANSACTION AGAINST THE POWERS ACTUALLY GRANTED. Gifts, beneficiary changes, and survivorship changes generally require EXPRESS authorization -- if the document does not contain them, the transfer was unauthorized on its face and you do not need to prove intent. Check the effective date too: an agent acting under a springing POA before the incapacity determination had no authority whatsoever. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [doc_code: EC-009 | pipeline: Power of Attorney Abuse] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: bd6ff2199a8690640508fe5da0f41b5e2e8890ff01c010857393149f56867264]', 'v1.0'),
('SAIS-EC-009-02', 'systemic_abuse_intelligence', 309, 'power_of_attorney_abuse', 'poa_abuse_fiduciary_duties', 'state', 'state -- ALL_STATES', 'Agent Fiduciary Duties -- Loyalty, Records, and the Duty to Preserve the Estate Plan', 'state_court', 'poa_abuse_fiduciary_duties', 'https://www.americanbar.org/groups/law_aging/', 'Your state bar lawyer referral service | Probate court self-help center | Dial 211 for legal aid', 'Uniform Power of Attorney Act (2006) sec. 114 (agent duties), sec. 102 (definitions), sec. 117 (agent liability) | State durable power of attorney statutes | State fiduciary and conversion law.', 'VERIFIED', '2026-08-17', 'THE RECORD-KEEPING DUTY IS THE EASIEST BREACH TO ESTABLISH AND THE ONE MOST OFTEN OVERLOOKED. An agent who cannot produce a record of receipts and disbursements has breached regardless of where the money went, and that failure alone supports court intervention. Note also that providing care does NOT entitle an agent to pay themselves from the principal''s funds -- compensation requires authorization in the document or from the court. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [doc_code: EC-009 | pipeline: Power of Attorney Abuse] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 1e0c7c4661eea00c97628e10c5f5ebef4b470645d67617040c352d933297a951]', 'v1.0'),
('SAIS-EC-009-03', 'systemic_abuse_intelligence', 309, 'power_of_attorney_abuse', 'poa_abuse_petition_to_compel_accounting', 'state', 'state -- ALL_STATES', 'Petition to Compel Accounting and Judicial Review of Agent Conduct', 'state_court', 'poa_abuse_petition_to_compel_accounting', 'https://www.lawhelp.org/', 'Your probate or superior court clerk | Court self-help center -- see jurisdiction table | Dial 211 for legal aid', 'Uniform Power of Attorney Act (2006) sec. 116 (judicial relief; persons entitled to petition), sec. 114(h) (accounting on request), sec. 117 (liability of agent) | State probate codes | State guardianship and protective proceedings statutes.', 'VERIFIED', '2026-08-17', 'FILE THE PETITION EVEN WITHOUT PROOF. Compelling an accounting does not require establishing misconduct first -- that is the entire point of the remedy, and the standing list is broad enough to include most concerned relatives. Ask in the same petition for SUSPENSION of the agent''s authority and an ASSET FREEZE; a court can grant those before any accounting is produced, and that timing is usually what determines whether anything remains. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [doc_code: EC-009 | pipeline: Power of Attorney Abuse] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: e19d09f306b40f793da50f0118668cb389c3b9244ae1521e375f79ce9d27c13c]', 'v1.0'),
('SAIS-EC-009-04', 'systemic_abuse_intelligence', 309, 'power_of_attorney_abuse', 'poa_abuse_revocation_and_notice', 'state', 'state -- ALL_STATES', 'Revoking the Power of Attorney and Making the Revocation Stick', 'state_court | financial_institution', 'poa_abuse_revocation_and_notice', 'https://www.uniformlaws.org/', 'County recorder (where the POA was recorded) | The principal''s banks, brokerages, and insurers | Your state bar lawyer referral service', 'Uniform Power of Attorney Act (2006) sec. 110 (termination), sec. 120 (acceptance and reliance; sanctions for improper refusal) | State durable power of attorney statutes | State recording acts.', 'VERIFIED', '2026-08-17', 'NOTIFY EVERY INSTITUTION IN WRITING AND RECORD THE REVOCATION WHERE THE ORIGINAL WAS RECORDED. Revocation delivered only to the agent leaves banks free to keep honoring their instructions, because a third party without actual notice may still be protected. And execute a replacement POA at the same time -- revoking without replacing is how families end up in a guardianship proceeding they did not want. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [doc_code: EC-009 | pipeline: Power of Attorney Abuse] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: ce0709f0d0db043cfe67499ed0f2f2a65b0cb81232b5d2d61afec08e386dbc40]', 'v1.0'),
('SAIS-EC-009-05', 'systemic_abuse_intelligence', 309, 'power_of_attorney_abuse', 'poa_abuse_reporting_and_asset_protection', 'federal + state', 'federal + state -- ALL_STATES', 'Reporting Agent Abuse and Freezing What Remains', 'state_agency | law_enforcement | financial_institution', 'poa_abuse_reporting_and_asset_protection', 'https://ovc.ojp.gov/program/stop-elder-fraud', 'DOJ National Elder Fraud Hotline: 833-372-8311 | Adult Protective Services via Eldercare Locator: 800-677-1116 | Local law enforcement | CFPB: 855-411-2372', 'Uniform Power of Attorney Act (2006) sec. 116 (APS standing to petition) | Senior Safe Act (Pub. L. 115-174, sec. 303) | FINRA Rules 2165 and 4512 | Electronic Fund Transfer Act / Regulation E (15 U.S.C. sec. 1693) | State vulnerable adult financial exploitation statutes.', 'VERIFIED', '2026-08-17', 'TELL ADULT PROTECTIVE SERVICES THAT A POWER OF ATTORNEY IS INVOLVED. In most states APS has express statutory standing to petition the court for review of an agent''s conduct, which means the accounting petition can be brought without a family member having to file it or fund it. Then notify every institution in writing and ask for holds and RECORD PRESERVATION the same day -- video is gone in 30 to 90 days. [address_resolution: Resolve via the state agency''s LOCAL OFFICE locator; input = ZIP or county. Most state agencies operate county or district offices rather than a single statewide address.] [doc_code: EC-009 | pipeline: Power of Attorney Abuse] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 5b4fe27e3ff77178af0323b9cfb2e951e7ea13282720391dcab3e079e05e6df7]', 'v1.0'),
('SAIS-EC-009-06', 'systemic_abuse_intelligence', 309, 'power_of_attorney_abuse', 'poa_abuse_recovery_and_successor', 'state', 'state -- ALL_STATES', 'Surcharge, Removal, Successor Agents, and Avoiding Guardianship', 'state_court', 'poa_abuse_recovery_and_successor', 'https://www.americanbar.org/groups/law_aging/', 'Your probate court clerk | Your state bar lawyer referral service | Dial 211 for legal aid and elder law referrals', 'Uniform Power of Attorney Act (2006) sec. 117 (agent liability), sec. 116 (judicial relief and fees) | Uniform Voidable Transactions Act | Uniform Guardianship, Conservatorship, and Other Protective Arrangements Act (2017) -- less restrictive alternatives | State forfeiture-on-exploitation provisions.', 'VERIFIED', '2026-08-17', 'DO NOT LET POA ABUSE BECOME AN AUTOMATIC GUARDIANSHIP PETITION. Ask about less restrictive alternatives by name -- supported decision-making, a finances-only limited conservatorship, a representative payee, a management trust. Courts in nearly every state must consider them, but they are rarely raised, and replacing a bad agent with a plenary guardianship trades one loss of autonomy for a larger and more permanent one. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [doc_code: EC-009 | pipeline: Power of Attorney Abuse] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 14f39da8e85e764ac6e448c6b894144e40bd16576aa273fbc084b78c895516bb]', 'v1.0'),
('SAIS-EC-010-01', 'systemic_abuse_intelligence', 310, 'elder_scam_recovery', 'elder_scam_stop_the_payment', 'federal', 'federal -- NATIONWIDE', 'Stop the Payment -- Every Payment Method Has a Different Clock', 'financial_institution | federal_agency', 'elder_scam_stop_the_payment', 'https://www.ic3.gov/', 'Your bank or credit union fraud department | FBI IC3: ic3.gov | DOJ National Elder Fraud Hotline: 833-372-8311 | AARP Fraud Watch Helpline: 877-908-3360', 'Electronic Fund Transfer Act / Regulation E (15 U.S.C. sec. 1693; 12 CFR Part 1005) | Fair Credit Billing Act (15 U.S.C. sec. 1666) | NACHA operating rules (unauthorized consumer debit returns) | 18 U.S.C. sec. 1343 (wire fraud) | Senior Safe Act (Pub. L. 115-174, sec. 303)', 'VERIFIED', '2026-08-17', 'FILE AT IC3.GOV TODAY IF ANY MONEY MOVED BY WIRE OR CRYPTOCURRENCY. The FBI Recovery Asset Team can work with banks to freeze fraudulent transfers, and the practical window is hours to a few days. Then call the sending institution and use the word RECALL. Everything else in this dossier still matters, but nothing else has this short a fuse. [address_resolution: Resolve via the institution''s own branch locator; input = ZIP. Fraud and exploitation matters are handled by a central department reachable from any branch.] [doc_code: EC-010 | pipeline: Elder Scam Recovery] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 60ce84f38b3533b517807fe0cc15b430682cd6511a8eea30008bfad8d6195db4]', 'v1.0'),
('SAIS-EC-010-02', 'systemic_abuse_intelligence', 310, 'elder_scam_recovery', 'elder_scam_reporting', 'federal + state', 'federal + state -- ALL_STATES', 'Reporting the Scam -- The Five Tracks and Why All Five', 'federal_agency | state_agency | law_enforcement', 'elder_scam_reporting', 'https://reportfraud.ftc.gov/', 'DOJ National Elder Fraud Hotline: 833-372-8311 | FBI IC3: ic3.gov | FTC: reportfraud.ftc.gov | Local police | Your state AG -- see jurisdiction table', 'Elder Abuse Prevention and Prosecution Act (Pub. L. 115-70) | 18 U.S.C. sec. 1341 (mail fraud), sec. 1343 (wire fraud), sec. 2326 (enhanced penalties for telemarketing fraud against persons over 55) | FTC Act sec. 5 (15 U.S.C. sec. 45) | Telemarketing Sales Rule (16 CFR Part 310)', 'VERIFIED', '2026-08-17', 'CALL 833-372-8311 FIRST. The DOJ National Elder Fraud Hotline assigns a case manager who routes the report to everyone with jurisdiction and follows up, which is exactly what a family in this situation cannot do on their own. Then get the police report number early -- institutions frequently will not reverse anything without one. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [doc_code: EC-010 | pipeline: Elder Scam Recovery] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 910b2b01a881bc354f9faf49a0ff3144c9ae8eb02a138684ed7f1ac8040ffc38]', 'v1.0'),
('SAIS-EC-010-03', 'systemic_abuse_intelligence', 310, 'elder_scam_recovery', 'elder_scam_typology', 'federal', 'federal -- NATIONWIDE', 'Scam Typology and the Pressure Mechanics That Make Them Work', 'federal_agency | nonprofit_organization', 'elder_scam_typology', 'https://consumer.ftc.gov/scams', 'AARP Fraud Watch Network Helpline: 877-908-3360 | FTC consumer alerts | DOJ National Elder Fraud Hotline: 833-372-8311', 'FTC Act sec. 5 (15 U.S.C. sec. 45) | Telemarketing Sales Rule (16 CFR Part 310) | 18 U.S.C. sec. 2326 (enhanced penalties for telemarketing fraud targeting persons over 55) | Senior Safe Act (Pub. L. 115-174, sec. 303)', 'VERIFIED', '2026-08-17', 'TEACH THE THREE SIGNATURES RATHER THAN THE STORIES: manufactured urgency, enforced secrecy, and an unusual payment method. The scripts change constantly; those three do not. And set a FAMILY CODE WORD today -- AI voice cloning has made the grandchild-in-trouble call convincing enough that recognizing the voice is no longer evidence of anything. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [doc_code: EC-010 | pipeline: Elder Scam Recovery] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 7365aa4453774fca5181d04155cb3485f7dfe190259373339514f98a3dab9b5a]', 'v1.0'),
('SAIS-EC-010-04', 'systemic_abuse_intelligence', 310, 'elder_scam_recovery', 'elder_scam_identity_hardening', 'federal', 'federal -- NATIONWIDE', 'Identity and Credential Hardening After a Scam', 'credit_reporting_agency | federal_agency', 'elder_scam_identity_hardening', 'https://www.identitytheft.gov/', 'FTC Identity Theft: 877-438-4338 | Annual Credit Report: 877-322-8228 | SSA: 800-772-1213 | IRS Identity Protection: 800-908-4490', 'Fair Credit Reporting Act (15 U.S.C. sec. 1681); identity theft block (sec. 1681c-2); business records disclosure (sec. 1681g(e)); security freeze (sec. 1681c-1) | Identity Theft and Assumption Deterrence Act (18 U.S.C. sec. 1028) | Social Security Act sec. 205 (42 U.S.C. sec. 405)', 'VERIFIED', '2026-08-17', 'FREEZE ALL THREE CREDIT BUREAUS TODAY AND CHANGE THE EMAIL PASSWORD FIRST, FROM A CLEAN DEVICE. The freeze is free and is the strongest single protection available; email is the master key that resets everything else. If any account was actually opened, use the FCRA identity theft BLOCK rather than an ordinary dispute -- it is mandatory and it operates in four business days. [address_resolution: No walk-in address applies -- disputes and freezes are handled by mail or online only. Use the published dispute mailing address.] [doc_code: EC-010 | pipeline: Elder Scam Recovery] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: f8bb19f11608cb0d3a163cf62d8cc58b1b3ca4d8d94c90c9c5d00abb484e8da8]', 'v1.0'),
('SAIS-EC-010-05', 'systemic_abuse_intelligence', 310, 'elder_scam_recovery', 'elder_scam_recovery_scam_defense', 'federal', 'federal -- NATIONWIDE', 'Recovery Scams -- Why Being Scammed Once Makes It More Likely Again', 'federal_agency | nonprofit_organization', 'elder_scam_recovery_scam_defense', 'https://consumer.ftc.gov/scams', 'FTC: reportfraud.ftc.gov | DOJ National Elder Fraud Hotline: 833-372-8311 | AARP Fraud Watch Helpline: 877-908-3360', 'FTC Act sec. 5 (15 U.S.C. sec. 45) | Telemarketing Sales Rule, advance-fee provisions (16 CFR 310.4(a)(4)) | 18 U.S.C. sec. 2326 (enhanced penalties, telemarketing fraud targeting persons over 55) | Telephone Consumer Protection Act (47 U.S.C. sec. 227) | State unclaimed property acts.', 'VERIFIED', '2026-08-17', 'WARN THE VICTIM NOW THAT A ''WE FOUND YOUR MONEY'' CALL IS COMING. It almost always does, victim lists are traded, and the second loss is frequently larger than the first because the target is desperate. The rule to leave them with is simple and absolute: NO GOVERNMENT AGENCY CHARGES A FEE TO RECOVER STOLEN MONEY, and legitimate recovery never asks for anything up front. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [doc_code: EC-010 | pipeline: Elder Scam Recovery] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 3be0940f7c58513762c292186294e37cb512646d2f6d5f34e28e5bc06c947869]', 'v1.0'),
('SAIS-EC-010-06', 'systemic_abuse_intelligence', 310, 'elder_scam_recovery', 'elder_scam_aftermath_and_support', 'federal + state', 'federal + state -- ALL_STATES', 'Aftermath -- Restitution, Tax Treatment, Benefit Impacts, and Support', 'federal_agency | state_agency | nonprofit_organization', 'elder_scam_aftermath_and_support', 'https://ovc.ojp.gov/program/stop-elder-fraud', 'DOJ Office for Victims of Crime | Your state crime victim compensation program | Eldercare Locator: 800-677-1116 | AARP Fraud Watch Helpline: 877-908-3360', 'Victims of Crime Act (34 U.S.C. sec. 20101 et seq.) | Crime Victims'' Rights Act (18 U.S.C. sec. 3771) | Mandatory Victims Restitution Act (18 U.S.C. sec. 3663A) | Elder Abuse Prevention and Prosecution Act (Pub. L. 115-70) | Older Americans Act (42 U.S.C. sec. 3001 et seq.)', 'VERIFIED', '2026-08-17', 'APPLY FOR CRIME VICTIM COMPENSATION AND ASK ABOUT COUNSELING COVERAGE -- it is available in most states, it is the most commonly needed and least claimed benefit in this pipeline, and there is a deadline. Then get ahead of the tax consequence: retirement withdrawals used to fund a scam are still taxable, and that bill arriving months later is the second injury nobody warns families about. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [doc_code: EC-010 | pipeline: Elder Scam Recovery] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 74299a2d48ac5a38d1b795a1058ccbebf45ce80a72cedec17016273fcc6b251d]', 'v1.0'),
('SAIS-EC-011-01', 'systemic_abuse_intelligence', 311, 'hospice_care_complaint', 'hospice_benefit_scope', 'federal', 'federal -- NATIONWIDE', 'The Medicare Hospice Benefit -- The Services the Hospice Agreed to Provide', 'federal_agency', 'hospice_benefit_scope', 'https://www.medicare.gov/care-compare/', 'Medicare: 800-633-4227 | TTY 877-486-2048 | Your state SHIP for free Medicare counseling | Medicare Care Compare', 'Medicare hospice benefit (42 U.S.C. sec. 1395d(a)(4), sec. 1395x(dd)) | Hospice Conditions of Participation (42 CFR Part 418) | Covered services (42 CFR 418.202) | Levels of care and payment (42 CFR 418.302) | Bereavement counseling requirement (42 CFR 418.64(d))', 'VERIFIED', '2026-08-17', 'ASK BY NAME FOR CONTINUOUS HOME CARE, GENERAL INPATIENT CARE, AND RESPITE CARE. Three of the four levels of hospice care exist specifically for uncontrolled symptoms and caregiver exhaustion, and families are routinely never told they exist. Then request the written PLAN OF CARE -- it states what the hospice promised, and nearly every valid complaint here is a gap between that document and what happened. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [doc_code: EC-011 | pipeline: Hospice Care Complaint] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 54c88d3c5e42a86743222776f44518ecb061754f928008bf2b1aba9d99c27d59]', 'v1.0'),
('SAIS-EC-011-02', 'systemic_abuse_intelligence', 311, 'hospice_care_complaint', 'hospice_patient_rights', 'federal + state', 'federal + state -- ALL_STATES', 'Hospice Patient Rights -- Notice, Participation, and Freedom From Abuse', 'federal_agency | state_survey_agency', 'hospice_patient_rights', 'https://www.medicare.gov/care-compare/', 'Medicare: 800-633-4227 | Your state survey agency -- see jurisdiction table | Long-Term Care Ombudsman if in a facility: 800-677-1116', 'Hospice Conditions of Participation -- Patient Rights (42 CFR 418.52) | Interdisciplinary group and plan of care (42 CFR 418.56) | Quality assessment and performance improvement (42 CFR 418.58) | Medicare hospice benefit (42 U.S.C. sec. 1395x(dd)) | HIPAA right of access (45 CFR 164.524)', 'VERIFIED', '2026-08-17', 'UNCONTROLLED PAIN IS A CITABLE DEFICIENCY, NOT AN UNAVOIDABLE PART OF DYING. Effective pain and symptom management is stated as a patient RIGHT at 42 CFR 418.52. Cite it by section. And request the interdisciplinary group review notes -- the plan of care must be reviewed at least every 15 calendar days, and a chart that cannot show those reviews carries a deficiency on its face. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [doc_code: EC-011 | pipeline: Hospice Care Complaint] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 9eb584e17089381dd2d309a33e0f7ad547495070ba6158a47e9f55b61ddf75c3]', 'v1.0'),
('SAIS-EC-011-03', 'systemic_abuse_intelligence', 311, 'hospice_care_complaint', 'hospice_discharge_and_appeals', 'federal', 'federal -- NATIONWIDE', 'Live Discharge, Revocation, and the Appeal Clock That Expires Overnight', 'federal_agency', 'hospice_discharge_and_appeals', 'https://www.medicare.gov/claims-appeals', 'Your Medicare BFCC-QIO (listed on the notice you receive) | Medicare: 800-633-4227 | Your state SHIP for free Medicare counseling', 'Hospice discharge and revocation (42 CFR 418.26, 418.28, 418.30) | Expedited determination procedures (42 CFR Part 405 Subpart J) | Medicare claims appeals (42 CFR Part 405 Subpart I) | 42 U.S.C. sec. 1395ff (determinations and appeals)', 'VERIFIED', '2026-08-17', 'CALL THE QIO NUMBER ON THE TERMINATION NOTICE THE DAY IT ARRIVES -- the fast-track deadline is generally NOON THE NEXT DAY and requesting on time keeps care in place during review. Separately: a hospice cannot revoke on a patient''s behalf. If anyone is pressuring a family to sign a revocation in order to get a hospitalization covered or to end services, that is reportable to the state survey agency and to the QIO. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [doc_code: EC-011 | pipeline: Hospice Care Complaint] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 64cd36ef3609b82acd936fea7e44cb66c3099bbd474eef808fff8e3833ed43a2]', 'v1.0')
